<?php if (isset($_GET['fio_checked'], $_GET['fio_paid']) && is_string($_GET['fio_checked']) && is_string($_GET['fio_paid']) && ctype_digit($_GET['fio_checked']) && ctype_digit($_GET['fio_paid'])): ?>
